class LRUCache {
    private static final class Node {
        final int key;          // needed to evict from the map
        int value;
        Node prev, next;
        Node(int key, int value) { this.key = key; this.value = value; }
    }

    private final int capacity;
    private final Map<Integer, Node> map = new HashMap<>();
    // Sentinels: every insert and removal is now unconditional pointer work.
    private final Node head = new Node(0, 0);
    private final Node tail = new Node(0, 0);

    LRUCache(int capacity) {
        this.capacity = capacity;
        head.next = tail;
        tail.prev = head;
    }

    public int get(int key) {
        Node node = map.get(key);
        if (node == null) return -1;
        unlink(node);          // a hit is a use
        addFirst(node);
        return node.value;
    }

    public void put(int key, int value) {
        if (capacity <= 0) return;

        Node existing = map.get(key);
        if (existing != null) {
            existing.value = value;
            unlink(existing);
            addFirst(existing);
            return;
        }

        if (map.size() == capacity) {
            Node lru = tail.prev;
            unlink(lru);
            map.remove(lru.key);        // this is why Node holds its key
        }

        Node fresh = new Node(key, value);
        map.put(key, fresh);
        addFirst(fresh);
    }

    private void addFirst(Node n) {
        n.prev = head;
        n.next = head.next;
        head.next.prev = n;
        head.next = n;
    }

    private void unlink(Node n) {
        n.prev.next = n.next;
        n.next.prev = n.prev;
        n.prev = n.next = null;   // help GC, and make use-after-unlink fail loudly
    }
}

class LRUCache:
    """OrderedDict is a hash map over a doubly linked list — the same structure,
    already written. Say that, then be ready to build it by hand anyway."""

    def __init__(self, capacity: int):
        self.capacity = capacity
        self.store: "OrderedDict[int, int]" = OrderedDict()

    def get(self, key: int) -> int:
        if key not in self.store:
            return -1
        self.store.move_to_end(key)        # O(1): relinks, does not copy
        return self.store[key]

    def put(self, key: int, value: int) -> None:
        if self.capacity <= 0:
            return
        if key in self.store:
            self.store.move_to_end(key)
        self.store[key] = value
        if len(self.store) > self.capacity:
            self.store.popitem(last=False)  # evict the oldest end
